#include "dstcrypt_private.h"
#include <string.h>

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
Boolean dstcrypt_set_isk(const UInt8 * isk , UInt8 size)
{
  if((size == DSTCRYPT_KEY40_SIZE) || (size == DSTCRYPT_KEY80_SIZE))
    {
      memset(&dstcrypt_nvfs_entry.isk[0] , 0   , DSTCRYPT_KEY80_SIZE) ;
      
      memcpy(&dstcrypt_nvfs_entry.isk[0] , isk , size) ;       
      
      #if DBG_DSTCRYPT == 1
        dstcrypt_dbg_print("\nDstCrypt Set Isk: " , isk , size) ;
      #endif    
      
      return TRUE ;
    }
  else
    {
      #if DBG_DSTCRYPT == 1
        dstcrypt_dbg_print("\nDstCrypt Isk Set Fail" , NULL , NULL) ;
      #endif    

    }
  return FALSE ;
}
